    sprintf_alt(buf, apostrophe ? D_L00_0015F858 : D_L00_0015F860);
    dy = apostrophe ? D_L00_0015F840 : D_L00_0015F848;
    dx = apostrophe ? D_L00_0015F83C : D_L00_0015F844;
